using namespace std;

long long read() {
    long long x = 0;
    int c = getchar(), sign = 1;
    while ((c < '0' || c > '9') && c != '-') c = getchar();
    if (c == '-') {
        sign = -1;
        c = getchar();
    }
    while (c >= '0' && c <= '9') {
        x = x * 10 + c - '0';
        c = getchar();
    }
    return x * sign;
}

int main() {
    long long n = read();
    int base = read();
    const int MAXK = 31;
    long long MOD = 1000000007;
    vector<int> digits;
    while (n > 0) {
        digits.push_back(n % base);
        n /= base;
    }
    int len = (int)digits.size();

    long long A[70][MAXK][MAXK], pre[MAXK][MAXK], suf[MAXK][MAXK], ans[MAXK][MAXK], I[MAXK][MAXK];

    auto init_identity = [&]() {
        memset(I, 0, sizeof(I));
        for (int i = 0; i <= base; ++i) I[i][i] = 1;
    };

    auto multiply = [&](long long A1[70][MAXK][MAXK], long long B[70][MAXK][MAXK], long long R[70][MAXK][MAXK]) {
        static long long C[70][MAXK][MAXK];
        memset(C, 0, sizeof(C));
        for (int i = 0; i <= base; ++i)
            for (int k = 0; k <= base; ++k)
                for (int j = 0; j <= base; ++j)
                    C[i][j] = (C[i][j] + A1[i][k] * B[k][j]) % MOD;
        memcpy(R, C, sizeof(C));
    };

    auto setup = [&]() {
        for (int i = 0; i < base; ++i) {
            for (int j = 0; j <= base; ++j) {
                A[0][i][j] = 0;
            }
            A[0][i][i] = 1;
            A[0][i][0] = 1;
        }
        for (int i = 1; i < len; ++i) {
            memcpy(pre[0], A[i - 1][0], sizeof(A[i - 1][0]));
            for (int j = 1; j < base; ++j) {
                multiply(A[i - 1][j], pre[j - 1], pre[j]);
            }
            memcpy(suf[base - 1], A[i - 1][base - 1], sizeof(A[i - 1][base - 1]));
            for (int j = base - 2; j >= 0; --j) {
                multiply(suf[j + 1], A[i - 1][j], suf[j]);
            }
            for (int j = 0; j < base; ++j) {
                if (j > 0) {
                    multiply(pre[j - 1], suf[j], A[i][j]);
                } else {
                    multiply(I, suf[j], A[i][j]);
                }
            }
        }
    };

    init_identity();
    setup();

    long long answer[MAXK][MAXK];
    memset(answer, 0, sizeof(answer));
    for (int i = 0; i <= base; ++i) answer[i][0] = (i == 0) ? 1 : 0;

    long long x = 0;
