import java.util.Scanner;

public class Main {
    static final int MAXK = 31;
    static final long MOD = 1000000007;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = read(sc);
        int base = sc.nextInt();
        int len;
        long[] digits;

        // Convert n to base representation
        {
            long tempN = n;
            int size = 0;
            while (tempN > 0) {
                size++;
                tempN /= base;
            }
            len = size;
            digits = new long[len];
            tempN = n;
            for (int i = len - 1; i >= 0; i--) {
                digits[i] = tempN % base;
                tempN /= base;
            }
        }

        long[][][] A = new long[70][MAXK][MAXK];
        long[][] pre = new long[MAXK][MAXK];
        long[][] suf = new long[MAXK][MAXK];
        long[][] ans = new long[MAXK][MAXK];
        long[][] I = new long[MAXK][MAXK];

        // Initialize identity matrix
        initIdentity(I, base + 1);

        // Setup matrices
        setup(A, pre, suf, I, base, len, digits, n);

        long[][] answer = new long[MAXK][MAXK];
        for (int i = 0; i < MAXK; i++) {
            for (int j = 0; j < MAXK; j++) {
                answer[i][j] = 0;
            }
        }
        for (int i = 0; i <= base; i++) {
            answer[i][0] = (i == 0) ? 1 : 0;
        }

        long x = 0;
        for (int i = len - 1; i >= 0; i--) {
            for (long j = 0; j < digits[i]; j++) {
                multiply(A[i][(int)((j + x) % base)], answer, answer);
            }
            x = (x + digits[i]) % base;
        }

        long res = 0;
        for (int i = 0; i < base; i++) {
            res = (res + answer[i][0]) % MOD;
        }
        System.out.println(res + 1);
        sc.close();
    }

    static long read(Scanner sc) {
        return sc.nextLong();
    }

    static void initIdentity(long[][] I, int size) {
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                I[i][j] = 0;
            }
        }
        for (int i = 0; i <= size; i++) {
            I[i][i] = 1;
        }
    }

    static void multiply(long[][] A1, long[][] B, long[][] R) {
        int size = B[0].length;
        long[][] C = new long[size][size];
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                C[i][j] = 0;
            }
        }
        for (int i = 0; i <= size; i++) {
            for (int k = 0; k <= size; k++) {
                for (int j = 0; j <= size; j++) {
                    C[i][j] = (C[i][j] + A1[i][k] * B[k][j]) % MOD;
                }
            }
        }
        // Copy result back to R
        for (int i = 0; i <= size; i++) {
            for (int j = 0; j <= size; j++) {
                R[i][j] = C[i][j];
            }
        }
    }

    static void setup(long[][][] A, long[][] pre, long[][] suf, long[][] I, int base, int len, long[] digits, long n) {
        for (int i = 0; i < base; i++) {
            for (int j = 0; j <= base; j++) {
                A[0][i][j] = 0;
            }
            A[0][i][i] = 1;
            A[0][i][0] = 1;
        }
        for (int i = 1; i < len; i++) {
            for (int j = 0; j <= base; j++) {
                for (int k = 0; k < base; k++) {
                    long[] temp = new long[MAXK];
                    // Copy A[i-1][0]
                    for (int l = 0; l <= base; l++) {
                        A[i][j][l] = 0;
                    }
                }
            }
            // Copy A[i-1][0]
            for (int j = 0; j <= base; j++) {
                for (int l = 0; l <= base; l++) {
                    A[i][j][l] = A[i - 1][0][l];
                }
            }

            for (int j = 1; j < base; j++) {
                multiply(A[i - 1][j], pre[j - 1], pre[j]);
            }
            for (int j = base - 2; j >= 0; j--) {
                multiply(suf[j + 1], A[i - 1][j], suf[j]);
            }
            for (int j = 0; j < base; j++) {
                if (j > 0) {
                    multiply(pre[j - 1], suf[j], A[i][j]);
                } else {
                    multiply(I, suf[j], A[i][j]);
                }
            }
        }
    }
}
